package repositories

import (
	"fmt"

	"Most/database"
	"Most/internal/players/models"
)

// CreatePlayer inserts a new player row and returns the player_id generated by SQLite.
func CreatePlayer(player models.Player) (int64, error) {
	result, err := database.Database.Exec(
		`INSERT INTO player (
			first_name,
			last_name,
			date_of_birth,
			position,
			category,
			height_cm,
			weight_kg,
			preferred_foot,
			previous_team,
			profile_image
		) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		player.FirstName,
		player.LastName,
		player.DateOfBirth,
		player.Position,
		player.Category,
		player.HeightCM,
		player.WeightKG,
		player.PreferredFoot,
		player.PreviousTeam,
		player.ProfileImage,
	)
	if err != nil {
		return 0, fmt.Errorf("can't insert player: %v", err)
	}

	playerID, err := result.LastInsertId()
	if err != nil {
		return 0, fmt.Errorf("can't read the generated player_id: %v", err)
	}

	return playerID, nil
}

// GetPlayers returns every player stored in the player table.
func GetPlayers() ([]models.Player, error) {
	rows, err := database.Database.Query(
		`SELECT
			player_id,
			first_name,
			last_name,
			date_of_birth,
			position,
			category,
			height_cm,
			weight_kg,
			preferred_foot,
			previous_team,
			profile_image
		FROM player
		ORDER BY player_id`,
	)
	if err != nil {
		return nil, fmt.Errorf("can't read players: %v", err)
	}
	defer rows.Close()

	players := []models.Player{}

	for rows.Next() {
		var player models.Player

		if err := rows.Scan(
			&player.PlayerID,
			&player.FirstName,
			&player.LastName,
			&player.DateOfBirth,
			&player.Position,
			&player.Category,
			&player.HeightCM,
			&player.WeightKG,
			&player.PreferredFoot,
			&player.PreviousTeam,
			&player.ProfileImage,
		); err != nil {
			return nil, fmt.Errorf("can't read player row: %v", err)
		}

		players = append(players, player)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("can't read players: %v", err)
	}

	return players, nil
}
